CREATE TABLE "Person" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "canonicalUrl" TEXT UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Person_name_canonicalUrl_key" ON "Person"("name","canonicalUrl");
CREATE TABLE "Affiliation" ("id" TEXT PRIMARY KEY, "personId" TEXT NOT NULL REFERENCES "Person"("id") ON DELETE CASCADE, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "sourceId" TEXT NOT NULL REFERENCES "Source"("id") ON DELETE CASCADE, "observedAt" TIMESTAMP(3), "passage" TEXT NOT NULL, UNIQUE("personId","companyId","sourceId","passage"));
CREATE TABLE "Contribution" ("id" TEXT PRIMARY KEY, "personId" TEXT NOT NULL REFERENCES "Person"("id") ON DELETE CASCADE, "companyId" TEXT NOT NULL REFERENCES "Company"("id") ON DELETE CASCADE, "sourceId" TEXT NOT NULL REFERENCES "Source"("id") ON DELETE CASCADE, "title" TEXT NOT NULL, "url" TEXT, "publishedAt" TIMESTAMP(3), "passage" TEXT NOT NULL, UNIQUE("personId","sourceId","title","passage"));
